ROOT=Path('.codex-tmp/math-20261120')
BASE=Path('2.知识库/20.North_star_ZJU/201.数学')
INV=json.loads((ROOT/'inventory.json').read_text(encoding='utf-8'))
IMAGES={i['image_id']:i for i in INV['images']}
CARDS=[]
def add(cid,category,title,ids,prompt,steps,pitfall,answer,main=True,refs=None):
 CARDS.append(dict(id=cid,category=category,title=title,images=ids,prompt=prompt,steps=steps,pitfall=pitfall,answer=answer,main=main,refs=refs or []))
C='一、概念选择：先看条件究竟管到了哪一步'
add('G01',C,'相邻两项的差趋于0，不代表整列停下来',['IMG155'],r'已知 $x_{n+1}-x_n\to0$。判断：①$x_n$必收敛；②加上单调就必收敛；③加上有界就必收敛；④加上$x_{3n}$收敛就必收敛。',[
 r'先把“每一步越来越小”和“最终停在某个数”分开：$x_n=\sqrt n$ 的差趋于0，但它单调趋于无穷，①②都不成立。',
 r'③试 $x_n=\sin\ln n$：有界、相邻差趋于0，却仍可沿不同子列趋于1和$-1$。',
 r'④把$n$分成$3k,3k+1,3k+2$。后两项与$x_{3k}$只差一项或两项差，每项都趋于0，所以三种余数的子列同极限。'],
 '“有界”和“单调”单独都不够，不能各自补成单调有界。',r'只有④正确，原题选A。')
add('G02',C,'数列的最值：极限值不是自动能取到',['IMG156'],r'$a_n=n^{1/n}$，$n=1,2,\ldots$。它能否取到最大值、最小值？',[
 r'先算$a_1=1$，而$n\ge2$时$a_n>1$，最小值已经取到。',
 r'比较大小先取对数，研究$h(x)=\ln x/x$；$h\prime(x)=(1-\ln x)/x^2$，在$e$前增、后减。',
 r'整数最大值只需比$n=2,3$。$3^{1/3}>\sqrt2$等价于$9>8$，所以最大值在3取得。'],
 '函数在实数上的极值点e，不是数列可以取的下标。',r'最小值1（$n=1$），最大值$\sqrt[3]3$（$n=3$）；原题选C。')
add('G03',C,'正项、无界，都不等于最终远离0',['IMG157'],r'$a_n,b_n>0$，$\{a_n\}$无界、$\{b_n\}$有界。判断哪一个一定有界：$b_n/a_n$；$b_n/(1+a_nb_n)$；$\sqrt[n]{a_nb_n}$；$a_nb_n-a_{n-1}b_{n-1}$（最后一式$n\ge2$）。',[
 r'先找直接的上界：$0<b_n/(1+a_nb_n)\le b_n$，第二个一定有界。',
 r'第一个要注意$a_n$可能隔一项很小：取$b_n=1$，奇数项$a_n=1/n^2$、偶数项$a_n=n$，商就无界。',
 r'第三个取$a_n=e^{n^2},b_n=1$；第四个取$a_n=n^2,b_n=1$，都能无界。'],
 '无界只表示不存在统一上界，不表示每一项都很大。',r'只有第二个一定有界，原题选B。')
add('G04',C,'导数的极限，和这一点的导数不是一回事',['IMG173'],r'判断四句话：①左右导函数极限都存在，则$f$在$x_0$连续；②左右导数都存在，则$f$在$x_0$连续；③左右函数极限都存在，则$f$在$x_0$连续；④左右导函数极限至少一个不存在，则$f$在$x_0$不可导。',[
 r'①③先试改坏单点：$f(x)=0$（$x\ne x_0$），$f(x_0)=1$。邻域内函数、导函数都很安静，单点仍不连续。',
 r'②左右导数的分子都包含$f(x_0)$；有限差商乘以$x-x_0\to0$，左右连续，所以整点连续。',
 r'④试$f(x)=x^2\sin(1/x)$（$x\ne0$），$f(0)=0$。$f\prime(0)=0$，但邻域导数振荡、无极限。'],
 '看清符号：$f\prime_+(x_0)$是带单点值的差商；$\lim_{x\to x_0^+}f\prime(x)$只看旁边的点。',r'仅②正确，原题选A。')
add('G05',C,'绝对值的可导性：非零点看符号，零点回定义',['IMG168'],r'$f$连续。下面四个双侧极限各自存在时，能否推出$f$在0可导？①$(|f(x)|-f(0))/x$；②$(f(x)-|f(0)|)/x$；③$|f(x)|/x$；④$(|f(x)|-|f(0)|)/x$。',[
 r'先利用有限极限和连续性，检查分子在0的极限必须为0。①②都迫使$f(0)\ge0$。',
 r'若$f(0)\ne0$，连续性保证附近同号，$|f|$就在附近等于$f$或$-f$，差商直接转回去。',
 r'若$f(0)=0$，$|f(x)|/x$的右侧非负、左侧非正；双侧极限只能为0。于是$|f(x)/x|\to0$，原导数也为0。③还先迫使$f(0)=0$。'],
 '零点处不能先假定f可导，再用其导数倒推。这里是从绝对值的差商直接夹出原差商。',r'四个条件都能推出可导，原题选D。')
add('G06',C,'绝对值有几个尖点：找零点，再查斜率',['IMG169'],r'若$f(x)=|\ln x-ax|$有两个不可导点，求$a$的范围。',[
 r'先只研究$g(x)=\ln x-ax$（$x>0$）。$|g|$只可能在$g=0$处出现尖点；简单零点会出现，水平零点需另查。',
 r'若$a\le0$，$g\prime=1/x-a>0$，只有一个简单零点，不符合。若$a>0$，最大值在$x=1/a$，值为$\ln(1/a)-1$。',
 r'要有两个简单零点，最大值必须大于0，即$0<a<e^{-1}$。等号时只碰到横轴、导数为0，不能算一个尖点。'],
 '“有两个零点”与“有两个不可导点”要靠零点处斜率接起来。',r'$0<a<e^{-1}$，原题选B。')
add('G07',C,'只给f连续：别直接把导数挪进积分',['IMG170'],r'$f$连续，$f(x)/x\to1$。令$g(x)=\int_0^1f(xt)\,dt$，求$g\prime(x)$并证明$g\prime$在0连续。',[
 r'连续性先给$f(0)=0$。对$x\ne0$换元$u=xt$，写$g(x)=F(x)/x$，其中$F(x)=\int_0^xf(u)\,du$。',
 r'用变上限积分求导：$g\prime(x)=[xf(x)-F(x)]/x^2$。由$f(x)=x+o(x)$，积分得$F(x)=x^2/2+o(x^2)$。',
 r'先按定义算$g\prime(0)=1/2$，再把前面的估计放入$x\ne0$的导数式，得$g\prime(x)\to1/2$。'],
 '题目没有给f可导，不能直接写积分号内的$t f\prime(xt)$。',r'$g\prime(0)=1/2$；$x\ne0$时$g\prime(x)=[xf(x)-\int_0^xf]/x^2$，且在0连续。')
add('G08',C,'两个极限先翻译成点值与导数，再判极值',['IMG171'],r'$f$有二阶导数，$\lim_{x\to0}[f(x)-a]/\ln(1+x)=0$，$\lim_{x\to0}[f\prime\prime(x)-1]/(e^{x^2}-1)=2021$。判断0是极大、极小、拐点还是都不是。',[
 r'第一式结合连续性和$\ln(1+x)\sim x$，得到$f(0)=a,f\prime(0)=0$。',
 r'第二式先给出$f\prime\prime(x)\to1$。不要把2021当二阶导的值；它描述的是更小的差。',
 r'因$f\prime$在0连续，利用中值定理得$f\prime\prime(0)=1$。二阶导正，0是严格极小值点。'],
 '分子和分母都趋于0，不代表它们的比值就是其中某个函数的点值。',r'极小值，原题选B。')
add('G09',C,'四阶主项，判断的是哪一条导函数曲线',['IMG172'],r'$f\in C^4$，$f(x)/x^4\to1$。判断：0是否为$f\prime\prime$的极小值点，$(0,0)$是否为$y=f\prime(x)$的拐点。',[
 r'用四阶泰勒系数比较，得到$f(0)=f\prime(0)=f\prime\prime(0)=f\prime\prime\prime(0)=0$，$f^{(4)}(0)=24$。',
 r'对$f\prime\prime$作泰勒：$f\prime\prime(x)=12x^2+o(x^2)$，所以0是严格极小值点。',
 r'看$y=f\prime(x)$的凹凸，要看它的二阶导$f\prime\prime\prime(x)=24x+o(x)$；两侧变号，所以有拐点。'],
 '问谁的拐点，就看谁的二阶导；别始终盯原函数。',r'两句话都成立，对应原题A。')
add('G10',C,'式子是一次的：先认出它连接了哪两个点',['IMG165'],r'$f$二阶可导，$g(x)=(1-x)f(0)+xf(1)$。在$[0,1]$上，$f\prime\prime\ge0$能推出$f\ge g$还是$f\le g$？仅$f\prime\ge0$够不够？',[
 r'g是连接$(0,f(0))$与$(1,f(1))$的直线：代两个端点就能认出来。',
 r'$f\prime\prime\ge0$时图像在这条割线下方，故$f(x)\le g(x)$；可用凸函数的弦不等式，或二阶插值余项证明。',
 r'只知道递增，管不住弯曲方向，$x^2$与$2x-x^2$就给出相反的割线位置。'],
 '用“图像在割线下、切线上”配合二阶导号，避免不同教材的凹凸命名把自己绕晕。',r'$f\le g$，原题选D。')
add('G11',C,'四个多元条件：先算原点，再估计附近',['IMG089'],r'$f(x,y)=\sqrt[3]{x^4+y^4}$。判断它在原点是否连续、偏导存在、可微、偏导连续。',[
 r'设$\rho=\sqrt{x^2+y^2}$，有$0\le f\le\rho^{4/3}$，先得到连续。沿坐标轴按定义求，两个偏导都为0。',
 r'可微要看$[f-f(0)-0x-0y]/\rho$，它不超过$\rho^{1/3}\to0$，所以可微。',
 r'非原点求$f_x=4x^3/[3(x^4+y^4)^{2/3}]$，其绝对值$\le(4/3)|x|^{1/3}\to0$；$f_y$同理，故偏导连续。'],
 '“在原点偏导为0”和“附近偏导趋于0”是两件事，第四问不能只重复第二问。',r'四项全成立，原题选D。')
add('G12',C,'积分只依赖x-y：先把它当一个变量',['IMG162'],r'$f$连续，$F(x,y)=\int_0^{x-y}(x-y-t)f(t)\,dt$。比较$F_x,F_y$及$F_{xx},F_{yy}$。',[
 r'先令$s=x-y$，写成$H(s)=\int_0^s(s-t)f(t)\,dt$。不要同时展开x和y两套式子。',
 r'求得$H\prime(s)=\int_0^sf(t)dt$，$H\prime\prime(s)=f(s)$。',
 r'一阶求导时$s_x=1,s_y=-1$，故$F_x=-F_y$；二阶再乘一次$-1$，故$F_{xx}=F_{yy}$。'],
 '上限处$(s-t)$为0，但积分号内也含s，不能因此把整个一阶导数判成0。',r'$F_x=-F_y$，$F_{xx}=F_{yy}=f(x-y)$；原题选C。')
add('G13',C,'求的是新变量的偏导：固定的变量也换了',['IMG163'],r'$f(x+y,y/x)=x^2-y^2$。求$f_u(1,1),f_v(1,1)$。',[
 r'令$u=x+y,v=y/x$，先反解$x=u/(1+v),y=uv/(1+v)$（目标点附近$1+v\ne0$）。',
 r'代回，得到$f(u,v)=u^2(1-v)/(1+v)$。',
 r'现在求$f_u$固定v，求$f_v$固定u；代$(1,1)$得$0,-1/2$。'],
 '原式右边对x求导，不等于新函数对u求偏导；复合链条不能丢。',r'$f_u(1,1)=0,f_v(1,1)=-1/2$；原题选D。')
V='05思维课做题记录/高数变式题.md'
add('G14',C,'导函数极限想落到单点：中间差一条连续性',[],r'$f$在$(-1,1)$连续，除0外可导，且$f\prime(x)\to A\in\mathbb R$。能否推出$f\prime(0)=A$？若删去连续性呢？',[
 r'写定义差商$[f(x)-f(0)]/x$，在0与x之间用中值定理，等于$f\prime(\xi_x)$。',r'$\xi_x\to0$，所以差商趋于A。删去连续性，给$f(0)$另改一个值就能破坏可导性。',r'不要反推“可导就导函数极限存在”；$x^2\sin(1/x)$在0的例子已说明不成立。'],
 '这条定理连起来的是“原函数连续＋旁边导数有极限”，不是只给旁边的导数。',r'保留连续性时必有$f\prime(0)=A$；删去则不保证。',refs=[(V,'第一类：补齐“连续性”补丁（考查原题 C 选项的成立边界）')])
add('G15',C,'高阶分母给出展开，不自动给出高阶导数',[],r'已知$\lim_{x\to0}[f(x)-2x]/x^2=3$。判断：①必有$f(0)=0,f\prime(0)=2$；②必有$f\prime\prime(0)=6$；③若f在0连续，则$f\prime(0)=2$；④$f\prime(0)$必存在但$f(0)$不确定。',[
 r'先只对$x\ne0$写$f(x)=2x+3x^2+o(x^2)$；极限还没规定$f(0)$，①④不能直接说。',r'加上连续性才有$f(0)=0$，再除以x，差商趋于2，③正确。',r'二阶导还要求邻域内有一阶导，并且其差商收敛；仅有这条函数值展开不够。即使连续，也可用更高阶小量叠加振荡破坏二阶导。'],
 '函数值的皮亚诺型展开不是“自动拥有相应阶导数”的充要条件。',r'只有③正确，原变式选C。',refs=[(V,'第二类：高阶分母逆推导数（考查你刚刚纠结的“分母为 0，分子必须为 0”）')])
add('G16',C,'长得像导数：先查是否包含f(0)、是否两侧都看',[],r'以下哪一个与f在0可导等价？①$\lim_{h\to0}[f(h)-f(-h)]/(2h)$存在；②$\lim[f(2h)-f(h)]/h$存在；③$\lim[f(h)-f(0)]/(h+h^2)$存在；④$\lim[f(h^2)-f(0)]/h^2$存在。',[
 r'③乘回$1+h\to1$，正好得到标准导数定义，所以它是充要条件。',r'①用$f(x)=|x|$否定：对称差商为0，左右导数不同。②用去心邻域取1、单点取0的函数否定。',r'④只沿$h^2\ge0$趋近，最多约束右导数；$|x|$仍是反例。'],
 '先检查采样到哪一侧、单点值有没有参与，再谈把分母凑成增量。',r'只有③，原变式选C。',refs=[(V,'第三类：充要条件辨析（考查导数定义中 $f(0)$ 的锁定）')])
add('G17',C,'一点斜率为正，只能先管这一点左右的函数值',[],r'$f$在$(-1,1)$可导且$f\prime(0)>0$。判断：①附近$f\prime$必正；②充分小的$x>0$有$f(x)>f(0)$；③$f\prime$可有跳跃间断；④$\lim_{x\to0}f\prime(x)$必存在。',[
 r'从$[f(x)-f(0)]/x\to f\prime(0)>0$出发，右侧x为正，推出②。',r'①④试$f(x)=x/2+x^2\sin(1/x)$，$f(0)=0$；在0导数为1/2，旁边导数仍可变号、振荡。',r'③不行：导数具有介值性，不能跳过中间值；若在可导点旁边的导函数有有限极限，反而必须等于该点导数。'],
 '证明在0右侧高于f(0)，不等于证明右侧任意两点之间都递增。',r'只有②，原变式选B。',refs=[(V,'第四类：导函数性质与振荡反例（考查原题 D 选项的逆向考核）')])
L='二、极限与数列大题：先把能控制的量写出来'
add('G18',L,'求和极限：先把n的幂次提干净',['IMG158'],r'求$\displaystyle\lim_{n\to\infty}\frac{\sqrt1+\cdots+\sqrt n}{\sqrt{n(1+\cdots+n)}}$。',[
 r'分子提成$n^{3/2}\,[\frac1n\sum_{k=1}^n\sqrt{k/n}]$，方括号才是积分和。',r'方括号趋于$\int_0^1\sqrt{x}\,dx=2/3$。分母为$n\sqrt{(n+1)/2}\sim n^{3/2}/\sqrt2$。',r'相同的$n^{3/2}$约掉，得到常数。'],
 '不要看到根号就把分子的n项和误估成n阶。',r'$2\sqrt2/3$。')
add('G19',L,'连乘带1/n次方：取对数后认积分和',['IMG075'],r'求$\displaystyle\lim_{n\to\infty}\frac1{n^2}\prod_{i=1}^{2n}(n+i)^{1/n}$。',[
 r'先把每项的n提出来，$2n$个$n^{1/n}$正好乘成$n^2$，与外面抵消。',r'剩下正数乘积$P_n=\prod_{i=1}^{2n}(1+i/n)^{1/n}$，写$\ln P_n=\frac1n\sum_{i=1}^{2n}\ln(1+i/n)$。',r'步长1/n、上限2，极限是$\int_0^2\ln(1+x)dx=3\ln3-2$。最后再指数还原。'],
 '积分区间是0到2，不是所有积分和都积0到1。',r'$27/e^2$。')
add('G20',L,'和减积分构成数列：用每个小区间的面积比较',['IMG159'],r'$f$在$[0,+\infty)$连续、非负、单调减少，$a_n=\sum_{k=1}^nf(k)-\int_1^nf(x)dx$。证明$a_n$极限存在。',[
 r'先作差：$a_{n+1}-a_n=f(n+1)-\int_n^{n+1}f(x)dx\le0$，因为该段上$f(x)\ge f(n+1)$。',r'再从另一个方向比面积：$\int_1^nf\le\sum_{k=1}^{n-1}f(k)$，故$a_n\ge f(n)\ge0$。',r'递减且下界为0，极限存在；不必分别证明原求和与反常积分收敛。'],
 '两个可能都趋于无穷的量相减，不能拆开取极限。',r'$a_n$单调不增，$0\le a_n\le f(1)$，故收敛。')
add('G21',L,'递推写在f里面：先比较目标值，再比较自变量',['IMG160'],r'$f$在实轴可导，$f(0)=1,f\prime(x)>1$。$x_1>0$，$f(x_{n+1})=f(x_n)-x_n$。①证明$x_n$收敛并求极限；②求$\lim\sum_{k=1}^nx_k$。',[
 r'设$g(x)=f(x)-x$，有$g\prime>0,g(0)=1$。若$x_n>0$，则$1<f(x_n)-x_n<f(x_n)$。',r'f严格递增，用中间值把$x_{n+1}$定位在$(0,x_n)$；归纳得整列递减、有下界0。',r'设极限L，代入原递推得$f(L)=f(L)-L$，所以L=0。',r'第二问不要另算：$x_k=f(x_k)-f(x_{k+1})$，有限和消项后为$f(x_1)-f(x_{n+1})$。'],
 '“不是显式递推”不等于没法单调有界。先在f的取值上比大小。',r'①$x_n\to0$；②和的极限为$f(x_1)-1$。')
add('G22',L,'迭代向唯一根靠近：估计误差，不必硬证单调',['IMG091'],r'$f\in C^1[0,2]$，$0<f(x)<2,|f\prime(x)|<1$。①证明$f(x)=x$在$(0,2)$有唯一根$x_0$；②$0<x_1<2,\ 2x_{n+1}=x_n+f(x_n)$，证明$x_n\to x_0$。',[
 r'对$g=f-x$，端点异号且$g\prime=f\prime-1<0$，得到唯一根。',r'令$F=(x+f(x))/2$。它把$(0,2)$送回自身，且$F(x_0)=x_0$，先保证每一步都能用。',r'连续导数在闭区间上有$k=\max|f\prime|<1$，从而$|F\prime|\le q=(1+k)/2<1$。中值定理给$|x_{n+1}-x_0|\le q|x_n-x_0|$。',r'迭代得$|x_n-x_0|\le q^{n-1}|x_1-x_0|\to0$。'],
 '你原来卡在“单调和数归不知道怎样起手”。这题直接估计距离更顺；详细版见[[01数列大题]]。',r'唯一根存在，且任意给定的$x_1\in(0,2)$产生的数列都趋于它。')
add('G23',L,'含n积分：中值点也会动，先给统一的上下界',['IMG161'],r'求$\displaystyle\lim_{n\to\infty}\int_0^1\frac{\sqrt[n]{1+n\arctan x^2}}{1+x^2}\,dx$。',[
 r'在整个$[0,1]$上，有$1\le\sqrt[n]{1+n\arctan x^2}\le(1+n)^{1/n}$。这两个界都不依赖x。',r'乘以正的$1/(1+x^2)$并积分，原式夹在$\pi/4$与$(\pi/4)(1+n)^{1/n}$之间。',r'两边都趋于$\pi/4$。若想用积分中值定理，也必须用这个统一估计管住随n变的$\xi_n$。'],
 '不是“小题放心用中值、大题才要夹逼”；两种写法都要有控制中值点的依据。',r'$\pi/4$。')
add('G24',L,'反常幂指式：先取对数，再把arctan换成小量',['IMG073','IMG127'],r'求$\displaystyle\lim_{x\to+\infty}(\pi/2-\arctan x)^{1/\ln x}$。（原图保存的是取对数后的中间式。）',[
 r'x为正时，$\pi/2-\arctan x=\arctan(1/x)$。设原式为y，写$\ln y=\ln[\arctan(1/x)]/\ln x$。',r'不要直接在对数里抹掉东西。准确拆成$\ln[\arctan(1/x)/(1/x)]-\ln x$。',r'前一项趋于0，再除以$\ln x\to+\infty$，所以$\ln y\to-1$，原式趋于$e^{-1}$。'],
 '“内层等价”不自动允许任意外函数替换；这里用对数恒等变形把理由写出来。',r'$e^{-1}$。题面由图中完整中间式还原，原图未另含独立小问。')
add('G25',L,'两个接近的自变量：用中值定理保住差的阶数',['IMG154'],r'$f\prime\prime$在0连续，$f\prime(0)=0,f\prime\prime(0)=1$。求$\displaystyle\lim_{x\to0}\frac{\int_0^x\{f(t)-f[\ln(1+t)]\}dt}{x^4}$。',[
 r'先比较自变量：$t-\ln(1+t)=t^2/2+o(t^2)$。',r'对两个函数值之差用中值定理：$f(t)-f(\ln(1+t))=f\prime(\xi_t)[t-\ln(1+t)]$，且$\xi_t/t\to1$。',r'由$f\prime(0)=0,f\prime\prime(0)=1$知$f\prime(\xi_t)=t+o(t)$，故被积函数为$t^3/2+o(t^3)$。',r'积分得到分子$x^4/8+o(x^4)$。'],
 '只把两个f分别写到二阶再相减，会留下无法直接控制的两个$o(t^2)$；这里要保住三阶差。',r'$1/8$。')
add('G26',L,'切线的横截距：先写切线，再把f除以f导数',['IMG164'],r'$f$二阶可导，$f\prime\prime(x)>0$且$f(x)/x\to0$。切线在x轴的截距为$u(x)$，$a_k=\lim_{x\to0^+}[u(x)/x]^k$。求$\lim_{n\to\infty}\sum_{k=1}^na_k$。',[
 r'由极限和可导性得$f(0)=f\prime(0)=0$。切线写$Y=f(x)+f\prime(x)(X-x)$，令Y=0，得$u=x-f/f\prime$。',r'$f\prime\prime(0)>0$，由定义与二阶泰勒，$f(x)=f\prime\prime(0)x^2/2+o(x^2)$，$f\prime(x)=f\prime\prime(0)x+o(x)$。',r'因此$u/x\to1/2$，固定k时$a_k=2^{-k}$，最后才求等比级数的和。'],
 '条件只够二阶时，别连续洛必达把未知的三阶导数弄出来。',r'$a_k=2^{-k}$，所求为1。')
add('G27',L,'函数方程：先代0，导数用增量来凑',['IMG076'],r'f在实轴连续，$f(x)f(y)=f(x+y)$，且$\lim_{x\to0}[1-f(x)]/x=1$。求$F(x)=|x|f(x)$的极值。',[
 r'极限给$f(0)=1$及$f\prime(0)=-1$。利用$f(x+h)=f(x)f(h)$，差商得到$f\prime(x)=-f(x)$。',r'解得$f(x)=e^{-x}$。把F在0两侧分开：x>0时$xe^{-x}$，x<0时$-xe^{-x}$。',r'右侧导数$(1-x)e^{-x}$在1由正变负；左侧导数$(x-1)e^{-x}<0$。0两侧函数值都正。'],
 '绝对值在0处要单独看，不能把正半轴的导数公式用到整条实轴。',r'0处极小值0；1处极大值$e^{-1}$。整条实轴无最大值。')
add('G28',L,'对所有整数n成立：先取对数，再把1/n换成连续变量',['IMG077','IMG078'],r'$f(x)=\ln^2(1+x)-x^2/(1+x)$。①求单调区间；②对所有正整数n都有$(1+1/n)^{n+k}\le e$，求k的最大值。',[
 r'定义域$x>-1$。令$t=1+x$，$f\prime=[2t\ln t-t^2+1]/t^2$。分子导数为$2(\ln t+1-t)\le0$，在t=1为0，故f在$(-1,0)$增、$(0,\infty)$减，且$f\le0$。',r'第二问取对数，改成$k\le h(1/n)$，其中$h(x)=1/\ln(1+x)-1/x$。',r'$h\prime=-1/[(1+x)\ln^2(1+x)]+1/x^2\le0$正好用第一问的$f\le0$。$1/n\in(0,1]$，所以h最小在1。'],
 '第二问的恒成立参数不是另起炉灶，第一问是在替你判断h的导数符号。',r'①$(-1,0)$增，$(0,+\infty)$减；②$k_{\max}=1/\ln2-1$。')
add('G29',L,'积分里是x-t：先换元，认出原函数乘其导数',['IMG153'],r'f非负连续，$f(x)\int_0^xf(x-t)dt=\sin^4x$。求f在$[0,\pi/2]$的平均值。',[
 r'令$F(x)=\int_0^xf(s)ds$；用$s=x-t$把题中积分也化为F(x)，所以$F\prime F=\sin^4x$。',r'两边积分，$F^2(x)=2\int_0^x\sin^4t\,dt$；$F(0)=0$，且非负性确定取正根。',r'$\int_0^{\pi/2}\sin^4t\,dt=3\pi/16$，再除以区间长度$\pi/2$，才是平均值。'],
 '先利用函数关系，别一上来独立计算f或者只去算sin的四次方。',r'平均值$\sqrt{3/(2\pi)}$。')
S='三、级数判敛：先找参照，或把相消写成部分和'
add('G30',S,'平方可求和：先把乘积拆成两个平方',['IMG198'],r'$\lambda>0$且$\sum a_n^2$收敛，判断$\sum(-1)^n|a_n|/\sqrt{n^2+\lambda}$是发散、条件收敛还是绝对收敛。',[
 r'先取绝对值，目标变为$|a_n|/\sqrt{n^2+\lambda}$，不需要先研究单调性。',r'用$2uv\le u^2+v^2$：$|a_n|/\sqrt{n^2+\lambda}\le\frac12[a_n^2+1/(n^2+\lambda)]$。',r'右侧两级数都收敛，直接比较。'],
 '不要只用a有界把它压到1/n，那样界太粗，判不出来。',r'绝对收敛，原题选C。')
add('G31',S,'通项趋于0加绝收：把平方压回已知项',['IMG182'],r'$a_n\to0$。判断：①$\sum b_n$收敛则$\sum a_nb_n$收敛；②$\sum b_n$发散则$\sum a_nb_n$发散；③$\sum|b_n|$收敛则$\sum a_n^2b_n^2$收敛；④$\sum|b_n|$发散则$\sum a_n^2b_n^2$发散。',[
 r'③从某项起$|a_n|,|b_n|\le1$，写$0\le a_n^2b_n^2\le|b_n|$，完成证明。',r'①取$a_n=b_n=(-1)^n/\sqrt n$，乘积成为调和级数。',r'②④取$a_n=1/n^2,b_n=1$，乘积级数与平方乘积级数都收敛。'],
 '找到有界因子后，剩下的必须是已知可求和的非负项，不能剩一个条件收敛级数就结束。',r'仅③，原题选C。')
add('G32',S,'nu与v/n不是多余条件：乘起来正好还原',['IMG200'],r'$\sum nu_n$绝对收敛，$\sum v_n/n$条件收敛。判断$\sum u_nv_n$的性质；以及$\sum(u_n+v_n)$能否必然判断。',[
 r'先写$|u_nv_n|=|nu_n|\,|v_n/n|$。第二个级数收敛，给出$v_n/n\to0$，所以它有界。',r'设$|v_n/n|\le M$，则$\sum|u_nv_n|\le M\sum|nu_n|<\infty$。',r'对$\sum(u_n+v_n)$，并没有得到$\sum v_n$的确定结论，不能附带说必收敛或必发散。取$u_n=0$，$v_n=(-1)^n/\ln(n+1)$时收敛；取$v_n=(-1)^n\sqrt n$时发散，二者的$\sum v_n/n$都条件收敛。'],
 '原题的正解不要求把每个变量都单独求出来。',r'乘积必绝对收敛，原题选B；加法敛散不定。')
add('G33',S,'数列与级数的充要条件：差分加起来就是端点',['IMG177','IMG178'],r'$a_n,b_n>0,b_1=1$，$b_{n+1}(b_{n+1}-b_n)=a_n$。证明“$b_n$收敛”和“$\sum a_n$收敛”等价。',[
 r'由$a_n>0$得$b_{n+1}>b_n\ge1$，差分为正。写$\sum_{n=1}^N(b_{n+1}-b_n)=b_{N+1}-1$。',r'若$b_n\to L<\infty$，则$a_n/(b_{n+1}-b_n)=b_{n+1}\to L\ge1$，两个正项级数同敛散，所以$\sum a_n$收敛。',r'反向若$\sum a_n$收敛，用$b_{n+1}\ge1$得到$0<b_{n+1}-b_n\le a_n$，差分级数收敛，所以$b_n$有有限极限。'],
 '反向证明还不知道b收敛，不能先写它的有限极限来套极限比较。',r'充分必要条件，原题选C。')
add('G34',S,'单调减少的正项，也可能不趋于0',['IMG104'],r'$u_n>0$单调减少。判断哪个级数必收敛：①$\sum(-1)^{n-1}u_n$；②$\sum u_n/n$；③$\sum(1-u_{n+1}/u_n)$；④$\sum(u_n-u_{n+1})/\sqrt{u_n}$。',[
 r'①②取$u_n=1+1/n$，前者通项不趋0，后者与调和级数同阶，都不保证。③取$u_n=1/n$，通项变$1/(n+1)$，发散。',r'④把差有理化：$(u_n-u_{n+1})/\sqrt{u_n}=(\sqrt{u_n}-\sqrt{u_{n+1}})(1+\sqrt{u_{n+1}/u_n})$。',r'它在0与$2(\sqrt{u_n}-\sqrt{u_{n+1}})$之间。有限和消项后不超过$2\sqrt{u_1}$，所以收敛。'],
 '莱布尼茨要“下降到0”，只有下降不够；最后一项不用猜你能否算出u的通项。',r'仅④，原题选D。')
add('G35',S,'相邻两项带交错号：先列项，别拿等价硬换',['IMG187'],r'$u_n\ne0,n/u_n\to1$。判断$\sum_{n=1}^{\infty}(-1)^{n+1}(1/u_n+1/u_{n+1})$的敛散与绝对收敛性。',[
 r'令$b_n=1/u_n\sim1/n$，原部分和准确等于$b_1+(-1)^{N+1}b_{N+1}$，所以收敛到$b_1$。',r'因为u最终为正，绝对值通项为$b_n+b_{n+1}\sim2/n$，绝对值级数发散。',r'两步合起来才叫条件收敛；不用先证$b_n+b_{n+1}$单调。'],
 '等价只用在已经转成正项的绝对值级数；原级数靠准确消项证明。',r'条件收敛，原题选C；和为$1/u_1$。')
add('G36',S,'条件收敛的交错项：奇偶正项各自都发散',['IMG194'],r'$u_n>0$，$\sum(-1)^{n-1}u_n$条件收敛。判断$\sum(2u_{2n}-u_{2n-1})$。',[
 r'先按连续两项分组，$\sum(u_{2n-1}-u_{2n})$收敛。',r'条件收敛意味着正项和$\sum u_{2n-1}$与$\sum u_{2n}$都发散到正无穷；否则会被前面的差连带推出全体绝收。',r'准确拆$2u_{2n}-u_{2n-1}=u_{2n}-(u_{2n-1}-u_{2n})$：发散到正无穷的正项部分减去收敛部分，仍趋于正无穷。'],
 '不是给每一项判正负，而是看有限部分和怎样拆。',r'发散到$+\infty$，原题选C。')
add('G37A',S,'指数里有1/n：先写成指数函数看多出来的因子',['IMG174'],r'判敛$\sum_{n=1}^{\infty}n^{-(1+1/n)}$。',[
 r'写成$\frac1n\exp[-(\ln n)/n]$，不要把指数大于1就当成p级数收敛。',r'它与$1/n$的比值为$e^{-\ln n/n}\to1$。',r'按正项极限比较，与调和级数同发散。'],
 'p级数判别中的p必须是固定常数；这里的指数在变化。',r'发散。')
add('G37B',S,'指数里有根号ln：换元后才看清衰减',['IMG174'],r'判敛$\sum_{n=2}^{\infty}n^{-(1+1/\sqrt{\ln n})}$。',[
 r'通项写为$1/[n e^{\sqrt{\ln n}}]$。它最终递减，可用积分判别。',r'积分中令$t=\sqrt{\ln x}$，则$dx/x=2t\,dt$。',r'尾部积分变为$\int 2te^{-t}dt$，收敛，所以原级数收敛。'],
 '虽然额外指数趋于0，但乘到ln n以后仍有足够衰减，不能凭“越来越像1/n”下结论。',r'收敛；与G37A合起来，对应原7.37选B。')
add('G38',S,'对数、交错、反复取对数：分开选参照',['IMG175'],r'判断哪项发散：①$\sum_{n\ge2}\sqrt{\ln n}/n^3$；②$\sum_{n\ge2}\ln n/n^2$；③$\sum_{n\ge2}(-1)^n/(n-\ln n)$；④$\sum_{n\ge3}1/[n\ln n\ln\ln n]$。',[
 r'①②中对数比任意正幂增长慢，分别用一个p>1的p级数从上面压住。',r'③$n-\ln n$在$n>1$递增且趋于无穷，倒数下降到0，用莱布尼茨；绝对值则与1/n同阶。',r'④用积分判别，依次令$t=\ln x$、$s=\ln t$，得到$\int ds/s$，发散。'],
 '交错项先检查单调与趋0；正项的对数连乘分母，不能只凭看起来很大就判收敛。',r'④发散，原题选D。')
add('G39A',S,'整项都在n次方下：第一行开n次根',['IMG197'],r'判敛$\sum_{n\ge1}[4n/(5n-2)]^n$。',[
 r'把通项开n次根，得到$4n/(5n-2)\to4/5$。',r'极限小于1，用根值判别。',r'有限的前面几项较大不影响敛散。'],
 '无需先对它求相邻比，根值已经把外面的n整齐消掉。',r'收敛。')
add('G39B',S,'先查通项：指数增长压过n的平方',['IMG197'],r'判敛$\sum_{n\ge1}[3^n+(-2)^n]/n^2$。',[
 r'提$3^n$，通项为$3^n[1+(-2/3)^n]/n^2$。方括号趋于1。',r'$3^n/n^2\to+\infty$，所以原通项不趋于0。',r'必要条件不满足，立即判发散。'],
 '不要把“分母有n平方”当作足够收敛，先看分子的增长。',r'发散。')
add('G39C',S,'n的ln n次方除以ln n的n次方：开根后再取对数',['IMG197'],r'判敛$\sum_{n\ge2}n^{\ln n}/(\ln n)^n$。',[
 r'开n次根，得$n^{\ln n/n}/\ln n$。',r'第一因子取对数为$(\ln n)^2/n\to0$，因此它趋于1；分母趋于无穷。',r'根值极限为0，小于1，收敛。'],
 '分子不是n次方，开根时要把原指数也除以n。',r'收敛。')
H='四、幂级数与傅里叶：半径、下标、端点各自核对'
add('G40',H,'三项递推先归纳出系数界，再把递推变成方程',['IMG176'],r'$a_0=1,a_1=0,(n+1)a_{n+1}=na_n+a_{n-1}$（$n\ge1$），$S(x)=\sum_{n\ge0}a_nx^n$。①证$R\ge1$；②证$(1-x)S\prime-xS=0$并求S。',[
 r'先归纳$|a_n|\le1$：前两项成立，递推右边绝对值不超过n+1。所以$|x|<1$时被$\sum|x|^n$控制。',r'在区间内部逐项求导：$S\prime=a_1+\sum_{n\ge1}(na_n+a_{n-1})x^n=xS\prime+xS$。',r'解一阶方程，或直接观察$[(1-x)e^xS]\prime=0$。代$S(0)=1$确定常数。'],
 '求导后常数项是a1，不要把递推从不允许的n=0硬套。',r'$R\ge1$；$S(x)=e^{-x}/(1-x)$（$|x|<1$）。',refs=[('04真题阶段/06卡片/01收敛半径.md','题型 A：递推式')])
add('G41',H,'要证半径下界：先猜一个够用的指数界',['IMG191'],r'$a_1=a_2=1,a_{n+1}=a_n+a_{n-1}$（$n\ge2$）。证明$\sum_{n\ge1}a_nx^{n-1}$在$|x|<1/2$收敛，并求和函数。',[
 r'归纳一个够用的界$a_n\le2^{n-1}$；从前两项起，右侧两项相加也不超过下一项的界。故绝对值被$\sum(2|x|)^{n-1}$控制。',r'设$S=a_1+a_2x+a_3x^2+\cdots$，分别写$xS,x^2S$，用递推相减，得$(1-x-x^2)S=1$。',r'在已证明收敛的区间内，解出$S=1/(1-x-x^2)$。若想算精确半径，还要找最近的奇点；本题第一问只要下界。'],
 '这次求和从x的0次开始，别误写成x/(1-x-x平方)。',r'$S=1/(1-x-x^2)$，题目要求的$|x|<1/2$内成立。实际$R=(\sqrt5-1)/2$。')
add('G42',H,'端点有震荡分母：把主项和余项准确拆开',['IMG192','IMG193'],r'求$\sum_{n\ge1}x^n/[n(3^n+(-2)^n)]$的收敛区间，并判端点。',[
 r'把分母写成$n3^n[1+(-2/3)^n]$，根值法得$R=3$，开区间$(-3,3)$。',r'x=3时为$1/[n(1+(-2/3)^n)]\sim1/n$，正项发散。',r'x=-3时用$1/(1+t)=1-t/(1+t)$，拆成交错调和项与余项。余项绝对值不超过$3(2/3)^n/n$，绝对收敛；原端点收敛，绝对值仍与1/n同阶。'],
 'x=-3时不能直接用变号通项等价；拆差后余项可求和才是依据。',r'开区间$(-3,3)$，收敛域$[-3,3)$；左端条件收敛，右端发散。')
add('G43',H,'积分定义系数：分部降幂后，倒数反而变成指数展开',['IMG189'],r'$a_n=\int_0^1x^2(\ln x)^n dx$（$n\ge0$）。①求$\lim(-1)^n/a_n$；②求$\sum_{n\ge0}x^n/a_n$的收敛域及和函数。',[
 r'$a_0=1/3$。分部积分，边界$x^3\ln^n x\to0$，得$a_n=-(n/3)a_{n-1}$。',r'迭代得到$a_n=(-1)^n n!/3^{n+1}$，所以$(-1)^n/a_n=3^{n+1}/n!\to0$。',r'把倒数代回：$\sum x^n/a_n=3\sum(-3x)^n/n!=3e^{-3x}$，对所有实数收敛。'],
 '题目给的是a，级数系数却是1/a；不要对a直接求半径就交卷。',r'①0；②收敛域$\mathbb R$，和函数$3e^{-3x}$。')
add('G44',H,'积分系数加隔两项：先把1+tan平方凑出来',['IMG186'],r'$a_n=\int_0^{\pi/4}\tan^nx\,dx$。①求$\sum_{n\ge1}(a_n+a_{n+2})/n$；②证任意$\lambda>0$时$\sum a_n/n^\lambda$收敛。',[
 r'先合并两个积分：$a_n+a_{n+2}=\int\tan^nx(1+\tan^2x)dx$。令$t=\tan x$，得$1/(n+1)$。',r'第一问变成$\sum1/[n(n+1)]$，有限和裂项，和为1。',r'第二问借第一步：$0<a_n\le a_n+a_{n+2}=1/(n+1)$，故$a_n/n^\lambda\le1/n^{1+\lambda}$，比较收敛。'],
 '不必先精确求a_n；第一问的等式已经给了第二问最顺手的上界。',r'①1；②对每个$\lambda>0$都收敛。')
add('G45',H,'方程给和函数：用奇偶性定常数，再按幂次取导数',['IMG185'],r'$S(x)=\sum_{n\ge1}a_{2n}x^{2n}$的收敛域为$[-1,1]$，且$xS\prime-S=x^2/(1+x^2)$。①求S；②求$S^{(m)}(0)$；③求$\sum_{n\ge1}a_{2n}/n$。',[
 r'x不为0时，$[S(x)/x]\prime=1/(1+x^2)$，所以$S=x\arctan x+Cx$。S是偶函数，C=0，且S(0)=0吻合。',r'展开$S=\sum_{n\ge1}(-1)^{n-1}x^{2n}/(2n-1)$。m为奇数则导数为0；m=2n时取对应系数乘$(2n)!$。',r'第三问先在0到r（r<1）积分$2S(x)/x$，产生$a_{2n}r^{2n}/n$；再令r上升到1。系数绝对值除以n可求和，允许过渡到端点。',r'直接算$2\int_0^1\arctan x\,dx=\pi/2-\ln2$。'],
 '不能只凭S(0)=0排掉Cx；它在0也为0，要用S只有偶次幂这一条件。',r'$S=x\arctan x$；$S^{(m)}(0)=0$（m奇），$S^{(2n)}(0)=(-1)^{n-1}(2n)!/(2n-1)$；第三问$\pi/2-\ln2$。')
add('G46',H,'偶次展开加一般展开：同次幂的两份贡献要相加',['IMG150'],r'$\cos2x-1/(1+x)^2=\sum_{n\ge0}a_nx^n$（$|x|<1$），求$a_n$。',[
 r'分别展开：余弦为$\sum_{k\ge0}(-1)^k4^kx^{2k}/(2k)!$；负分式为$\sum_{n\ge0}(-1)^{n+1}(n+1)x^n$。',r'目标n为奇数时，余弦没有贡献；n为偶数时，令k=n/2，把余弦的系数取出来。',r'偶次系数还要加上负分式的贡献；最后单独试n=0，应该为0。'],
 'x的2k次方只有在目标n是偶数时才能令k=n/2；不能把整个级数的下标一律对半。',r'$a_n=\begin{cases}n+1,&n\text{奇},\\(-1)^{n/2}2^n/n!-(n+1),&n\text{偶}.\end{cases}$')
add('G47',H,'傅里叶和函数：单点取值不决定跳点的和',['IMG196'],r'$f(x)=-1$（$-\pi<x<0$），$f(x)=1$（$0\le x\le\pi$），作$2\pi$周期傅里叶展开，求$[-\pi,\pi]$上的和函数S。',[
 r'区间内部非跳点，傅里叶和等于原函数。',r'0处左右极限是-1和1，平均为0；不是照抄f(0)=1。',r'$\pm\pi$处要看周期拼接，左右也分别是1与-1，平均仍为0。'],
 '端点处向另一侧看时，要看下一个周期，不是说“题目没给所以不能算”。',r'$S=-1$（$-\pi<x<0$），$S=1$（$0<x<\pi$），$S(-\pi)=S(0)=S(\pi)=0$。')
add('G48',H,'余弦展开后求交错平方和：代点前先看哪些项留下',['IMG195'],r'将$f(x)=1-x^2$（$0\le x\le\pi$）展开为余弦级数，并求$\sum_{n\ge1}(-1)^{n-1}/n^2$。',[
 r'余弦展开对应偶延拓：常数项为$1-\pi^2/3$；对$n\ge1$，分部积分得$a_n=4(-1)^{n-1}/n^2$。',r'所以$f(x)=1-\pi^2/3+4\sum(-1)^{n-1}\cos(nx)/n^2$，在本区间端点也连续。',r'代x=0，左边为1，余弦都等于1，直接解出所求和。'],
 '常数项是a0的一半，不是a0；求和时先代点再识别符号。',r'展开如步骤；所求$\pi^2/12$。')
add('G49',H,'正弦与余弦展开：函数相同，延拓不同',['IMG190'],r'将$f(x)=x^2$（$0<x<\pi$）分别作正弦级数与余弦级数展开，并检查端点的和。',[
 r'正弦用奇延拓，$b_n=(2/\pi)\int_0^\pi x^2\sin nx\,dx$；余弦用偶延拓，$a_n=(2/\pi)\int_0^\pi x^2\cos nx\,dx$。各作两次分部积分。',r'余弦常数为$\pi^2/3$，$a_n=4(-1)^n/n^2$；正弦系数见折叠结果，别把两套符号混用。',r'正弦在0与π的和都为0（π处奇周期延拓有跳跃）；余弦在两端的和为0和$\pi^2$。区间内部两者都等于$x^2$。'],
 '半区间展开不只是“删掉另一类系数”，它选择了不同的延拓。',r'$x^2=\pi^2/3+4\sum_{n\ge1}(-1)^n\cos nx/n^2$；正弦系数$b_n=-2\pi(-1)^n/n+4[(-1)^n-1]/(\pi n^3)$，$0<x<\pi$。')
add('G50',H,'先证明相邻差绝对可求和，再得整个数列收敛',['IMG201'],r'$f$可导，$f(0)=1,0<f\prime(x)<1/2$，$x_{n+1}=f(x_n)$。①证$\sum(x_{n+1}-x_n)$绝对收敛；②证$x_n$有极限L且$0<L<2$。',[
 r'中值定理给$|x_{n+2}-x_{n+1}|\le\frac12|x_{n+1}-x_n|$，差的绝对值被等比数列控制，第一问成立。',r'差分级数有限和为$x_{N+1}-x_1$，故x有有限极限L；连续性给$L=f(L)$。',r'若L\le0，利用f递增及斜率小于1/2可推出$f(L)>1+L/2>L$，矛盾，所以L>0。正L时$L=f(L)<1+L/2$，所以L<2。'],
 '不能先假定x已收敛再用极限证明差分收敛；第一问本来就在帮你建立收敛依据。',r'差分级数绝对收敛，$x_n\to L\in(0,2)$。')
add('G51',H,'两个半径已知：逐项乘的半径不能总写成乘积',['IMG066'],r'已知$\sum a_nx^n,\sum b_nx^n$半径分别为$R_a,R_b\in(0,+\infty)$，能否断言$\sum a_nb_nx^n$半径为$R_aR_b$？',[
 r'仅知两个上极限，最大增长可能出现在不同下标，不能把上极限的乘积直接当乘积的上极限。',r'例：a只在偶数下标取1，b只在奇数下标取1，两者半径都是1，但乘积系数全0，新半径无穷。',r'若另有普通根值极限分别存在且为正，或有效的相邻系数比值极限存在，就可把极限相乘，得到半径乘积。'],
 '这里是逐项乘a_n b_n，不是两个和函数相乘后的卷积系数。',r'一般不能；需额外的增长极限条件。',main=False)
add('G52',S,'正部分与负部分：绝对值是相加，原通项是相减',['IMG069'],r'令$u_n=(|a_n|+a_n)/2,v_n=(|a_n|-a_n)/2$。判断：①$\sum a_n$收敛则$\sum u_n,\sum v_n$都收敛；②$\sum|a_n|$收敛则其余三个都收敛；③$\sum u_n,\sum v_n$都发散则$\sum a_n,\sum|a_n|$都发散。',[
 r'先写$u_n,v_n\ge0$，$u_n+v_n=|a_n|,u_n-v_n=a_n$。',r'②用$0\le u_n,v_n\le|a_n|$直接比较，再用绝收推出原级数收敛。',r'①③用交错调和级数：原级数收敛，正、负两部分各自都发散，所以都不成立。'],
 '正、负部分的“负部分”v本身是非负的幅度，不是一个负数。',r'只有②正确，对应原题B。')
add('G53',S,'绝收加条件收：反证时把b凑回来',[],r'$\sum a_n$绝对收敛、$\sum b_n$条件收敛。判断$\sum(a_n+b_n)$、$\sum a_nb_n$、$\sum(a_n-|b_n|)$以及$\sum b_n/n$是否必条件收敛。',[
 r'和级数先由线性运算知收敛。若它绝收，写$|b_n|\le|a_n+b_n|+|a_n|$，推出b绝收，矛盾。',r'乘积反而必绝收：b_n趋0所以有界，压到$M|a_n|$即可。$a_n-|b_n|$的部分和趋于负无穷。',r'b_n/n并非必条件收：例如$b_n=(-1)^n/\sqrt n$，除以n后绝收。无需为此选项证明它在所有情形的敛散。'],
 '原批注中三角不等式一度写成减号；这里右边必须是两项绝对值相加。',r'只有和级数必条件收敛，对应旧变式“级数1·题1”选A。',main=False,refs=[(V,'级数')])
add('G54',S,'正项可求和，开根后不能只凭交错号保证收敛',[],r'$u_n>0,\sum u_n$收敛。判断$\sum\ln(1+u_n)$、$\sum\sin u_n$、$\sum u_n/(1+u_n)$、$\sum\sqrt{u_nu_{n+1}}$、$\sum\sqrt{u_n}/n$、$\sum(-1)^n\sqrt{u_n}$，哪个不一定收敛。',[
 r'前3个从某项起与u同阶（且非负），都收敛。',r'第4个用$\sqrt{u_nu_{n+1}}\le(u_n+u_{n+1})/2$；第5个用$\sqrt{u_n}/n\le(u_n+1/n^2)/2$。',r'最后取$u_{2k}=1/k^2,u_{2k-1}=1/k^4$，每项严格为正且总和有限；成对求和却是$1/k-1/k^2$，发散。'],
 '旧答案给奇数项取0，与“正项”严格口径不符；这里换成1/k的四次方，反例才完整。',r'最后一项不一定收敛，对应旧变式F。',main=False,refs=[(V,'级数')])
add('G55',S,'乘上交错号再除n：原来的收敛可能被破坏',[],r'已知$a_n\to0$。“$\sum a_n$收敛”是“$\sum(-1)^na_n/n$收敛”的充分条件、必要条件、充要条件，还是都不是？',[
 r'先否定充分：取$a_{2k-1}=1/\ln(k+1),a_{2k}=-1/\ln(k+1)$。原级数成对为0，且组内剩项趋0，所以收敛。',r'目标级数每一项却都为负，每组约为$-1/[k\ln(k+1)]$，发散到负无穷。',r'再否定必要：取$a_n=1/n$，原级数发散，目标$\sum(-1)^n/n^2$绝对收敛。'],
 '旧变式答案A及其狄利克雷论证错误；有界的不是凭空假设的“交错加权后部分和”。',r'既非充分也非必要，旧变式“级数1·题3”应选D，不是A。',refs=[(V,'级数')])
add('G56',S,'两份绝收式子里解出b：先做代数减法',[],r'$\sum a_n$与$\sum(a_n+2b_n)$都绝对收敛，判断$\sum b_n$。',[
 r'第一行先解$b_n=[(a_n+2b_n)-a_n]/2$，不要先猜b的正负。',r'取绝对值，$|b_n|\le[|a_n+2b_n|+|a_n|]/2$。',r'右边的级数收敛，比较得b绝收。'],
 '把未知项用已知可求和的项凑出来，再取绝对值，而不是对无穷和做未经证明的运算。',r'必绝对收敛，旧特训1选A。',main=False,refs=[(V,'2')])
add('G57',S,'条件收敛时，只留下正部分会怎样',[],r'$u_n\ne0,\sum u_n$条件收敛。判断$\sum(u_n+|u_n|)$。',[
 r'先看$u_n+|u_n|\ge0$，它相当于把负项抹掉、正项加倍。',r'若它收敛，则$\sum|u_n|=\sum(u_n+|u_n|)-\sum u_n$也收敛，和条件收敛矛盾。',r'因为新项非负，发散的方向就是正无穷。'],
 '不需要u是按正负交错排列，只用条件收敛的定义就够。',r'发散到$+\infty$，旧特训2选C。',main=False,refs=[(V,'2')])
add('G58',S,'不等式右边非负，又已知其级数收敛：别漏掉这个条件',[],r'$\sum a_n,\sum b_n$均收敛，$\sum c_n$绝对收敛，且$|a_n|\le b_n+c_n$。判断a、b是否必绝对收敛；原题还问“a绝收”与“b绝收”的条件关系。',[
 r'令$d_n=b_n+c_n$。题设强制$d_n\ge|a_n|\ge0$，同时$\sum d_n$收敛（两个收敛级数相加）。',r'因此$\sum|a_n|\le\sum d_n<\infty$。再写$|b_n|=|d_n-c_n|\le d_n+|c_n|$，推出b也绝收。',r'所以在本题全部条件下，两件事都必然成立；若仍按给定的四选一问条件关系，应为充要，不是旧答案B。'],
 '旧解析只盯“小者推不出大者”，漏了右边本来就是非负且收敛，构造不出它声称的反例。',r'a、b都必绝对收敛；旧特训3应选C（在题设范围内），不是B。',refs=[(V,'2')])
add('G59A',H,'条件收敛的点能锁定中心：不是只锁定半径',['IMG180'],r'$\sum_{n\ge1}(x-a)^n/n$在$x=-2$条件收敛。判断$\sum_{n\ge1}n^2(x-a)^n$在$x=\ln(1/2)$的敛散。',[
 r'先对变量t=x-a认$\sum t^n/n$：t=1发散，t=-1条件收敛。故$-2-a=-1$，a=-1。',r'新级数仍有半径1，但要代的是t=x+1。',r'目标点t=1-\ln2在(0,1)，处于内部，所以绝对收敛。'],
 '你原来已标“消灭”；只作为低频核对，不能重新塞进每天主练。',r'绝对收敛，原题选A。',main=False)
add('G59B',H,'两项递推先算比值，再把它求和成微分方程',['IMG181'],r'$a_0=1,2na_n=(n+3/2)a_{n-1}$（$n\ge1$）。①求$\sum a_nx^n$的半径；②求开区间内的和函数。',[
 r'$a_n/a_{n-1}=(n+3/2)/(2n)\to1/2$，所以R=2。',r'乘$x^{n-1}$并从n=1求和，得$2S\prime=xS\prime+(5/2)S$，即$(2-x)S\prime=(5/2)S$。',r'解方程并代S(0)=1，得到$(1-x/2)^{-5/2}$。'],
 'n改成n-1后，括号里的常数3/2也要跟着算成5/2。原题已标消灭，低频看。',r'$R=2,S(x)=(1-x/2)^{-5/2}$（$|x|<2$）。',main=False)
add('G59C',H,'指定展开中心：先设t等于x减中心',['IMG183'],r'将$1/(x^2+3x+2)$在x=1处展开为幂级数，并求收敛域。',[
 r'先拆成$1/(x+1)-1/(x+2)$，令t=x-1，变成$1/(t+2)-1/(t+3)$。',r'分别提常数凑几何级数，系数是$(-1)^n(2^{-n-1}-3^{-n-1})$。公共开区间|t|<2。',r'两端x=-1、3代入后通项都不趋0，所以端点都发散。'],
 '展开中心是1，不是让公式里出现x的n次就算展开完。原题已消灭，留备用。',r'$\sum_{n\ge0}(-1)^n(2^{-n-1}-3^{-n-1})(x-1)^n$，收敛域$(-1,3)$。',main=False)
add('G59D',H,'系数下标2n、指数4n：先统一成真正的计数器',['IMG184'],r'$\sum_{n\ge0}a_{2n}(x-1)^{2n}$在x=5条件收敛，求$\sum_{n\ge0}n a_{2n}^2(x-3)^{4n+1}$的开收敛区间。',[
 r'令c_n=a_{2n},t=(x-1)^2。原级数在t=16条件收敛，所以$\sum c_nt^n$半径是16。',r'系数平方把半径变成$16^2=256$，乘n不改变半径。新变量是s=(x-3)^4，外面还乘x-3。',r'解$|x-3|^4<256$，得到$|x-3|<4$。本题只问开区间，不额外猜端点。'],
 '不能把a的下标2n忽略后，再把所有半径机械平方一次。原题已消灭，留低频。',r'$(-1,7)$，原题选B。',main=False)
add('G59E',H,'负一处展开平方分母：先改成1+t的负二次方',['IMG199'],r'将$1/(x+2)^2$在x=-1处展开，并求收敛域。',[
 r'令t=x+1，原式是$1/(1+t)^2$。从$1/(1+t)$的几何展开求导，得到$\sum_{n\ge0}(-1)^n(n+1)t^n$。',r'开区间|t|<1，即-2<x<0。',r'两端通项大小为n+1，都不趋0，所以都发散。'],
 '本题也已标消灭，作为展开中心和起点的备用核对即可。',r'$\sum_{n\ge0}(-1)^n(n+1)(x+1)^n$，收敛域$(-2,0)$。',main=False)
add('G59F',H,'反正切展开：先求导，绕开复合分式',['IMG105'],r'将$f(x)=\arctan[(1+x)/(1-x)]$在0展开，并给出收敛域内的表达。',[
 r'在0附近求导得$f\prime(x)=1/(1+x^2)$，且f(0)=π/4。',r'先展开导函数$\sum_{n\ge0}(-1)^nx^{2n}$，从0积分，得到$\pi/4+\sum_{n\ge0}(-1)^nx^{2n+1}/(2n+1)$。',r'级数在-1、1都收敛；x=-1时原函数也有定义且等于0，x=1原函数无定义，但级数和为π/2。'],
 '“级数收敛域”和“与原函数等值的定义域”要分开说，尤其x=1不能替原函数补定义。',r'级数收敛域$[-1,1]$；在$[-1,1)$与原函数相等，x=1的级数和π/2。')
A='五、线面积分：先认微元，再定方向和区域'
add('G60',A,'梯度点乘有向微元：这是全微分，不是弧长积分',['IMG112'],r'L是曲面边界闭曲线，方向符合右手法则，求$\oint_L\operatorname{grad}\sin(x+y+z)\cdot d\vec s$。',[
 r'先读点乘：$d\vec s=(dx,dy,dz)$，不是非负弧长ds。令u=sin(x+y+z)。',r'$\operatorname{grad}u\cdot d\vec s=u_xdx+u_ydy+u_zdz=du$，沿曲线积就是终点减起点。',r'L闭合，起终点相同，所以结果0。也可用光滑梯度场的旋度为0配斯托克斯，但不必绕远。'],
 '区分向量微元与标量弧长；公式里的点乘号已经在提示。',r'0。')
add('G61',A,'一型有正弧长，二型还要看x往哪里走',['IMG113'],r'单位圆逆时针，L1、L2、L3依次为第一、第二、第三象限圆弧。f>0且$f(x,-y)=f(x,y)$。比较$I_1=\int_{L1}f\,dx,I_2=\int_{L2}f\,ds,I_3=\int_{L3}f\,dx$。',[
 r'L1上x从1减到0，故I1<0；L2上ds非负、f>0，I2>0；L3上x从-1增到0，I3>0。',r'把L3关于x轴反射到L2，f不变。相同弧段上$|dx|<ds$（除个别点外严格），所以I3<I2。',r'合并符号和大小，得到I2>I3>I1。'],
 '不要把dx当成总是正的小长度；第一型即使反向走，ds也不变号。',r'$I_2>I_3>I_1$，原题选B。图示仍可从原图核对。')
add('G62',A,'一型曲线的根号很丑：隐函数求导后可能正好约掉',['IMG086'],r'L为$x^2+y^2-xy=1$在第二象限从(-1,0)到(0,1)的一段，求$\int_L (y^2-xy)(2y-x)/\sqrt{5-3xy}\,ds$。',[
 r'隐式求导得$y\prime=(y-2x)/(2y-x)$。第二象限上2y-x>0，故$ds=\sqrt{5-3xy}\,dx/(2y-x)$。',r'这正好与题中两块因子抵消，积分变为$\int_{-1}^0(y^2-xy)dx$。',r'利用原曲线等式$y^2-xy=1-x^2$，最后只积一个多项式。'],
 'ds公式里本来有绝对值；这里能去掉，是先查了第二象限的符号。',r'$2/3$，原题选C。')
add('G63',A,'椭圆整体偏移：先写中心和两个半轴',['IMG088'],r'L为椭圆$4x^2+(y-2)^2=4$，逆时针，求$\oint_L|x|dy-y\,dx$。',[
 r'先除以4，中心(0,2)，半轴1和2。参数写$x=\cos t,y=2+2\sin t,0\le t\le2\pi$。',r'第一项变成$\int_0^{2\pi}2|\cos t|\cos t\,dt=0$，在t与t+π处相消。',r'第二项$-\oint ydx$等于逆时针包围的面积，也可代参数算，结果2π。'],
 '你原批注是“椭圆不会画”。先标准化方程，比直接凭印象猜半轴可靠。',r'$2\pi$。')
add('G64',A,'两项凑一个全微分，剩下的再用对称性',['IMG114'],r'L从$A(-\pi,0)$沿$y=\cos(x+\pi/2)$到$B(\pi,0)$，求$\int_L(2x+y-\cos y)dx+x\sin y\,dy$。',[
 r'先合并$-\cos y\,dx+x\sin y\,dy=-d(x\cos y)$，别分别硬积分。',r'$2x\,dx=d(x^2)$，因此剩下$\int_Ly\,dx$。用y=-sin x、x从-π到π，这一项为0。',r'最后只算端点：$[x^2-x\cos y]_A^B=-2\pi$。'],
 '全微分要连着两项一起认；不要先把每项都代成难算的三角复合函数。',r'$-2\pi$。')
add('G65',A,'路径无关先列偏导相等，别把分母全展开',['IMG116'],r'第一象限内$P=yf(2y/x)-2xy^2/(x^2+4y^2)$，$Q=xf(2y/x)+2x^2y/(x^2+4y^2)$，$Pdx+Qdy$路径无关，f有连续导数且$f(1)=\pi/4$。①求f；②沿$y=x^2-2x+2$从(1,1)到(2,2)求积分。',[
 r'先写$P_y=Q_x$，设t=2y/x整理；把$x^2+4y^2$当整体保留，最后得到$f\prime(t)=1/(1+t^2)$（t>0）。',r'由f(1)=π/4得$f(t)=\arctan t$。认出势函数$U=xy\arctan(2y/x)$，实际求一下Ux、Uy核对。',r'积分等于U(2,2)-U(1,1)，曲线的具体形状不再需要。'],
 '“应该能约掉”只能提醒你先提公因式，不能代替真正求偏导；交叉的链式因子2/x与-2y/x平方别漏。',r'$f(t)=\arctan t$（t>0）；积分$3\arctan2$。')
add('G66',A,'开口抛物面通量：先把侧翻译成法向量分量',['IMG118'],r'$\Sigma:y=1-2x^2-2z^2$，$0\le y\le1$，取右侧（法向量y分量为正），求$\iint_\Sigma(xy^2+x)dydz+(y^3-z^2)dzdx+(zy^2-x^2)dxdy$。',[
 r'把面投到xz平面，D为$x^2+z^2\le1/2$。选取$\boldsymbol n\,dS=(4x,1,4z)\,dx\,dz$，y分量为正，先固定方向。',r'代入点乘，得到$4(x^2+z^2)y^2+4x^2+y^3-z^2-4x^2z$。D关于z对称，最后一项为0；再用轮换把$4x^2-z^2$积成$(3/2)r^2$。',r'代y=1-2r²，转极坐标，积分为$\pi\int_0^{1/2}[(1-2t)^2(1+2t)+3t/2]dt$，t=r²。'],
 '“右侧”先写成法向量分量正负，避免坐标画法不同导致记反；该图面选y为投影变量最省。',r'$19\pi/48$。若题设选反侧，整体取负。')
add('G67',A,'闭空间曲线用斯托克斯：先把观察方向换成法向量',['IMG141'],r'L为单位球与$x+y+z=3/2$的交圆，从原点向L看为顺时针。求$\oint_L2yz\,dx+(2z-z^2)dy+(y^2+2xy+3y)dz$。',[
 r'选平面圆盘作面。给定从原点看的顺时针，对应正法向量$(1,1,1)/\sqrt3$；先把这个方向写下来。',r'旋度为$(2(x+y+z)+1,0,-2z)$，在平面上成为$(4,0,-2z)$，点乘单位法向量得$(4-2z)/\sqrt3$。',r'圆心(1/2,1/2,1/2)，半径1/2，面积π/4；z的一次项积分是圆心z坐标乘面积。'],
 '轮换或形心用于平面圆盘上的积分；不能把球面的半径1误当截圆半径。',r'$\sqrt3\pi/4$。')
add('G68',A,'一型空间圆：曲线等式先代入，积分可能只剩长度',['IMG204','IMG205'],r'$a>0$，L为$x^2+y^2+z^2=a^2$与$x+y+z=3a/2$的交圆，求$\oint_L(2xy+2yz+2zx)ds$。（原图第3题。）',[
 r'先把被积函数写为$(x+y+z)^2-(x^2+y^2+z^2)$，在L上等于常数$5a^2/4$。',r'球心到平面的距离为$\sqrt3a/2$，截圆半径$\sqrt{a^2-3a^2/4}=a/2$。',r'一型积分只剩常数乘周长πa。'],
 '不是所有空间圆都要写三角参数；先把给你的两个等式用进去。',r'$5\pi a^3/4$。')
add('G69',A,'大圆上的平方项：三项地位相同，先加起来',['IMG204','IMG205'],r'L为$x^2+y^2+z^2=1$与$x+y+z=0$的交圆，求$\oint_L(x^2+y^2)ds$。（原图第4题。）',[
 r'完整圆周在x、y、z互换下不变，所以三个平方项的积分相等。',r'原积分等于$\frac23\oint_L(x^2+y^2+z^2)ds=\frac23\oint_Lds$。',r'平面过球心，截圆半径1、周长2π。'],
 '轮换对称性检查的是整个积分曲线和ds，不是只看到球面方程对称就用。',r'$4\pi/3$。')
add('G70',A,'偏心圆的一次项：平移后奇项归零',['IMG204','IMG205'],r'C为$x^2+y^2=2(x+y)$，求$\oint_C(2x^2+3y^2)ds$。（原图第5题。）',[
 r'圆心(1,1)、半径√2，关于y=x对称，所以$x^2$和$y^2$的积分相等，原式是$(5/2)\oint(x^2+y^2)ds$。',r'利用圆周方程，变成$5\oint(x+y)ds$。',r'写$x+y=(x-1)+(y-1)+2$，前两项关于圆心相消；只剩10倍周长。'],
 '偏心圆不能直接把x或y的一次项判成0，要先减去圆心坐标。',r'$20\sqrt2\pi$。')
add('G71',A,'根号到原点的距离：极坐标比平移参数更顺',['IMG206','IMG207'],r'L为$x^2+y^2=-2y$，求$\oint_L\sqrt{x^2+y^2}\,ds$。',[
 r'被积函数是到原点的距离r，优先试极坐标。曲线为$r=-2\sin\theta$，取$-\pi\le\theta\le0$保证r非负且走一周。',r'$ds=\sqrt{r^2+(r\prime)^2}\,d\theta=2d\theta$，所以积分为$-4\int_{-\pi}^0\sin\theta\,d\theta$。',r'算得8。若用圆心平移参数，也能做，但会产生绝对值，需要另找变号点。'],
 '极坐标的r在所选区间必须非负；别为套0到2π让同一个公式走错。',r'8。')
add('G72',A,'上半球通量：补底盘后别漏掉它的负号',['IMG203'],r'$u=z(x^2+3)$，求$\operatorname{grad}u$穿过单位球上半球面外侧的通量。',[
 r'先求场$\boldsymbol F=(2xz,0,x^2+3)$，散度是2z。补上z=0底盘，形成上半球体外侧。',r'体积分$\iiint2z\,dV=\pi/2$；底盘外法向量朝下，通量为$-\iint_D(x^2+3)dxdy=-13\pi/4$。',r'闭面通量=上半球+底盘，故原通量$\pi/2-(-13\pi/4)$。也可直接投影，上半球点乘后化成$3\iint_D(x^2+1)$。'],
 '题目问grad u的通量，不是把u本身乘面积；补面算出来为负也要按代数关系减。',r'$15\pi/4$。')
add('G73',A,'球面上分母可直接换成R：先试点乘再说高斯',['IMG106'],r'$\Sigma$为半径R>0球面外侧，求$\iint_\Sigma[x(y-z)dydz+y(z-x)dzdx+z(x-y)dxdy]/\sqrt{x^2+y^2+z^2}$。',[
 r'球面上分母就是R，单位外法向量为$(x,y,z)/R$。直接改成一型面积积分，分子变为$x^2(y-z)+y^2(z-x)+z^2(x-y)$，分母R²。',r'拆开后每项都对某一个坐标为奇，在完整球面上积分为0。',r'无需求散度；若用高斯，还要注意这个场在原点分母为0，不能直接无视公式条件。'],
 '原题曾标消灭，但这次线面仍不稳，作为短概念复测保留；不要为了用高斯反而引入内部奇点。',r'0。')
add('G74',A,'法向导数乘ds：先换成平面通量形式',['IMG208','IMG213','IMG214'],r'L为圆$x^2+y^2=R^2$，逆时针，n为单位外法向量，u有连续二阶偏导，$u_{xx}+u_{yy}=x^2+y^2$。求$\oint_L(\partial u/\partial n)ds$。',[
 r'逆时针单位切向量为$(dx/ds,dy/ds)$，向右转90度才是外法向量，所以$n\,ds=(dy,-dx)$。',r'因此原式$\oint_Lu_xdy-u_ydx$。用格林通量公式变成$\iint_D(u_{xx}+u_{yy})dxdy$。',r'代入题目，极坐标算$\int_0^{2\pi}\int_0^Rr^3drd\theta$。'],
 'n必须是单位方向；不要把方向导数直接当成普通偏导，更别把外法向量转向写反。',r'$\pi R^4/2$。原题及手写同题只收这一张。')
add('G75',A,'切平面条件先给轨迹，面积因子可能正好抵消',['IMG074','IMG144'],r'$S:x^2+y^2+z^2-yz=1$。①求切平面与xOy垂直的点的轨迹C；②Σ为S在C上方部分，求$\iint_\Sigma (x+\sqrt3)|y-2z|/\sqrt{4+y^2+z^2-4yz}\,dS$。',[
 r'令F为曲面左边减1，法向量$(2x,2y-z,2z-y)$。切平面与xOy垂直，两个法向量点乘为0，得y=2z；与原曲面联立即C。',r'上方Σ投到D：$x^2+3y^2/4\le1$。隐函数投影有$dS=|\nabla F|/|F_z|\,dxdy$，不必先解出z。',r'曲面上$|\nabla F|=\sqrt{4+y^2+z^2-4yz}$，$|F_z|=|2z-y|$，两块都抵消，原式变$\iint_D(x+\sqrt3)dxdy$。',r'奇项x归零，椭圆面积$2\pi/\sqrt3$，剩下常数乘面积。'],
 '你的旧题里“有绝对值就想偶倍”会在这里卡住。先把绝对值同投影因子配对，它可以直接消掉。',r'$C:\ y=2z,\ x^2+3y^2/4=1$；积分$2\pi$。')
add('G76',A,'一型与二型曲面积分：上下两块皮的符号不同',['IMG146','IMG147','IMG148'],r'Σ为整个椭球$x^2/4+y^2/9+z^2=1$外侧。分别判断$\iint_\Sigma(x^4+y^2\sin z)dS$和$\iint_\Sigma(x^4+y^2\sin z)dxdy$是否为0。',[
 r'第一型上下反射时dS不变，sin z项相消，剩$\iint x^4dS>0$。',r'第二型投到同一xy椭圆，外侧的上半面正、下半面负。上下相减后，x四次项相消，sin z项反而加倍。',r'上半面0<z\le1，所以$\sin z>0$，剩$2\iint_Dy^2\sin\sqrt{1-x^2/4-y^2/9}\,dxdy>0$。'],
 '二型对称性要把所选侧的法向量也带进去，不能直接照搬一型。',r'两个都非0，且都为正。')
add('G77',A,'二重积分的分母很烦：交换x和y后再加起来',['IMG097'],r'$D:(x-1)^2+(y-1)^2\le1$，求$\iint_D(1+x^2)(x^2+y^2-xy)/(2+x^2+y^2)\,dxdy$。',[
 r'D在x、y互换后不变。把原被积函数和交换后的式子相加除2，分母正好消去，变为$\frac12\iint_D(x^2+y^2-xy)$。',r'令u=x-1,v=y-1。括号变成$u^2+v^2-uv+u+v+1$，在单位圆盘上奇项都归零。',r'$\iint(u^2+v^2)=\pi/2$，常数项积分π，再乘1/2。'],
 '偏心不妨碍交换对称，只要圆心本身就在y=x上；但不要见恶心分母就断言一定能约。',r'$3\pi/4$。')
B='六、空间几何与其余薄弱：把对象写对再计算'
add('G78',B,'最大方向导数还要在曲线上取最大：分成两层',['IMG092','IMG093'],r'$u=x^2+2y^2+z^2$，Γ满足$z=x^2+4y^2,x+2y+z=1$。求u在Γ上的最大方向导数。',[
 r'先固定一点，最大方向导数是$|\nabla u|=2\sqrt{x^2+4y^2+z^2}$。在Γ上用第一条等式化成$2\sqrt{z+z^2}$。',r'令s=x,t=2y，则z=s²+t²，s+t=1-z。由$(s+t)^2\le2(s^2+t^2)$，得$(1-z)^2\le2z$，即$2-\sqrt3\le z\le2+\sqrt3$。',r'z\ge0时z+z²递增，上端可在s=t时取到。因此把z=2+√3代入即可。'],
 '你原来消掉约束中的z，却在目标里还留着自由z。消元必须同时改掉所有出现的位置。原题u的y平方系数为2，不是梯度模平方中的4。',r'$2\sqrt{9+5\sqrt3}$；可在$x=(-1-\sqrt3)/2,y=(-1-\sqrt3)/4,z=2+\sqrt3$取到。')
add('G79',B,'方向向量先单位化，方向导数才是所求标量',['IMG211'],r'$f=x^2y+z^2$，求(1,2,0)处沿向量(1,2,2)的方向导数。',[
 r'先求梯度，代点得$\nabla f=(4,1,0)$。',r'给定向量模长3，单位方向是$(1,2,2)/3$。',r'点乘得(4+2)/3=2。'],
 '直接点乘原向量会多乘一个长度3；最大方向导数则是梯度模，不是本题给定方向的值。',r'2，原题选D。')
add('G80',B,'直线落在切平面里：先把切平面写出来',['IMG209'],r'直线由$x+y+b=0,x+ay-z-3=0$给出，且落在抛物面$z=x^2+y^2$在(1,-2,5)处的切平面π内，求a,b。',[
 r'切平面先写成$2x-4y-z-5=0$，这是已经确定的对象。',r'直线的两个平面法向量为(1,1,0)、(1,a,-1)。π包含直线，所以π方程应是两个平面方程的线性组合。',r'比z系数得第二个方程乘1，比x系数得第一个也乘1；再比y系数及常数，得a=-5,b=-2。'],
 '先写出你已经能写的方程，不要等未知参数都求完才动笔。',r'$a=-5,b=-2$。')
add('G81',B,'绕轴对称的曲面：法线的x、y分量按同一比例走',['IMG210'],r'$z=f(\sqrt{x^2+y^2})$，$f\prime\ne0$且$x_0^2+y_0^2\ne0$。判断该点法线与z轴的关系：垂直相交、不垂直相交、平行、异面。',[
 r'设$r_0=\sqrt{x_0^2+y_0^2}$，法向量可取$(-f\prime(r_0)x_0/r_0,-f\prime(r_0)y_0/r_0,1)$。',r'法线上x、y都等于原坐标乘同一个因子$1-\lambda f\prime(r_0)/r_0$。令该因子0，可同时到达x=y=0，所以相交。',r'法向量z分量为1，因此不与z轴垂直；横向分量也不全为0，因此不平行。'],
 '“旋转曲面的法线与轴相交”要用非零导数与非零半径保障；题目给的条件不是装饰。',r'不垂直相交，原题选B。')
add('G82',B,'切平面过直线：一个点在面内，加方向垂直法向量',['IMG212'],r'求椭球$x^2+2y^2+3z^2=21$的切平面，使它经过直线$(x-6)/2=(y-3)=(2z-1)/(-2)$。',[
 r'设切点(a,b,c)，先写切平面$ax+2by+3cz=21$，并保留$a^2+2b^2+3c^2=21$。',r'直线上一点(6,3,1/2)，方向(2,1,-1)。点代入平面，方向点乘法向量为0，得到$6a+6b+3c/2=21,\ 2a+2b-3c=0$。',r'解得c=2,a+b=3；再代回椭球，得到(a,b)=(3,0)或(1,2)，分别写平面。'],
 '直线最后一项分母是-2，但分子是2z-1，真正的z方向增量是-1。',r'切点(3,0,2)、(1,2,2)；平面$x+2z=7$、$x+4y+6z=21$。')
add('G83',B,'直线绕相交直线旋转：先找顶点和夹角',['IMG202'],r'$l_1:(x-2)=(y-3)/2=(z-2)/2$，$l_2:(x-1)=(y-1),z=0$。①求交点和夹角；②求l1绕l2旋转所得曲面。',[
 r'用l1参数s，由z=0得s=-1，交点A=(1,1,0)。方向向量v1=(1,2,2)、v2=(1,1,0)，夹角满足cosθ=1/√2。',r'整个l1绕相交轴旋转成双圆锥。设r=(x-1,y-1,z)，它与轴方向v2的夹角余弦绝对值是1/√2。',r'写$(r\cdot v_2)^2=|r|^2|v_2|^2\cos^2\theta$，化简为$z^2=2(x-1)(y-1)$。'],
 'l2里分母0的写法表示z恒为0，不是真的拿z去除以0。',r'交点(1,1,0)，夹角π/4；曲面$z^2=2(x-1)(y-1)$。')
add('G84',B,'锥面由顶点和准线给出：先写母线参数',['IMG084'],r'锥顶A=(0,1,1)，准线$x^2+y^2=1,z=0$。①求过A与准线上$M_1=(x_1,y_1,0)$的直线及锥面方程；②求0≤z≤1的锥体形心。',[
 r'母线写$(x,y,z)=(0,1,1)+t(x_1,y_1-1,-1)$。由t=1-z，得x=(1-z)x1、y-z=(1-z)y1。',r'用$x_1^2+y_1^2=1$消掉准线参数，得$x^2+(y-z)^2=(1-z)^2$。',r'高度z的截面是圆心(0,z)、半径1-z的圆盘。体积$\pi\int_0^1(1-z)^2dz=\pi/3$；y矩与z矩都为$\pi\int_0^1z(1-z)^2dz=\pi/12$，x矩为0。'],
 '这是斜锥，截面圆心会随高度移动；不能按直圆锥误设y的形心为0。',r'母线见步骤；锥面$x^2+(y-z)^2=(1-z)^2$；形心$(0,1/4,1/4)$。')
add('G85',B,'微分方程问一点的极值：先代值，不急着求通解',['IMG099'],r'$f\prime-P(x)f=\tfrac12e^x-1$，$f(0)=1,P(x)=\int_0^1|x-t|dt$。判断f在0的极值或拐点。',[
 r'先求P(0)=1/2。原方程代0，得f\prime(0)=0。',r'只需0附近：x≤0时P=1/2-x，0≤x≤1时P=x²-x+1/2，所以P\prime(0)=-1。',r'对原方程求一次导，$f\prime\prime=P\prime f+Pf\prime+e^x/2$，代0得-1/2，故严格极大。'],
 '这题真正要的是原点附近的导数信息，不是全实轴上的完整解。',r'0处严格极大值，原题选A。')
add('G86',B,'只对x求偏导：把y当参数，常数也可能依赖y',['IMG117'],r'$f_x(x,y)+f(x,y)=xy$，且$f(0,y)=y$，求f。',[
 r'对每个固定y，把它看作关于x的一阶线性方程，乘积分因子e的x次方：$(e^xf)_x=xye^x$。',r'对x积分，$f=y(x-1)+C(y)e^{-x}$。积分“常数”必须允许随y变化。',r'代x=0得C(y)=2y。'],
 '原来漏齐次解的问题，就在这里保留C(y)e的负x次方，不能只写一个特解。',r'$f(x,y)=y(x-1+2e^{-x})$。')
add('G87',B,'二元极值：先利用每个偏导的因子分情况',['IMG119'],r'求$f(x,y)=(x^2+y^2)e^{-(x^2+2y^2)}$的极值。',[
 r'写$f_x=2xe^{-x^2-2y^2}(1-x^2-y^2)$，$f_y=2ye^{-x^2-2y^2}(1-2x^2-2y^2)$。',r'先分x=0、y=0；若两者都非零，会要求半径平方同时等于1与1/2，不可能。驻点只有原点、(±1,0)、(0,±1/√2)。',r'原点f≥0所以极小；(±1,0)二阶型负定，极大；(0,±1/√2)两坐标方向的二阶符号相反，是鞍点。',r'还可用$f\le r^2e^{-r^2}\le1/e$核对最大值。'],
 '别把两条偏导方程直接相等，先看各自等于0能带来什么。',r'原点极小值0；(±1,0)极大值1/e（也是全局最大）；另外两点不是极值。')
add('G88',B,'三阶方程就列三阶特征根，重合指数要多乘x',['IMG120'],r'解$y\prime\prime\prime-2y\prime\prime-3y\prime=e^{3x}$，$y(0)=-1/36,y\prime(0)=0,y\prime\prime(0)=1/4$。',[
 r'特征多项式$r(r-3)(r+1)$，齐次解为C1+C2e的3x次方+C3e的负x次方。不要因为没有y项就漏掉r=0的常数解。',r'右边e的3x次方与单根3重合，特解设Ax e的3x次方，代入得A=1/12。',r'把完整解及一、二阶导代初值，求得C1=C3=0,C2=-1/36。'],
 '题目三阶，必须保留3个齐次常数再上初值；不要套成二阶公式。',r'$y=(3x-1)e^{3x}/36$。')
add('G89',B,'球内积分只看半径：先用球坐标，再求导',['IMG109'],r'$f\in C[0,+\infty)$，$f(t)=\iiint_{x^2+y^2+z^2\le t^2}f(\sqrt{x^2+y^2+z^2})dV+t^3$。求f(1)。',[
 r'径向函数的角度积分给4π，原式变为$f(t)=4\pi\int_0^tf(r)r^2dr+t^3$，且f(0)=0。',r'右边可导，于是$f\prime(t)=4\pi t^2f(t)+3t^2$。令g=f+3/(4π)，化为$g\prime=4\pi t^2g$。',r'积分并代g(0)=3/(4π)，再取t=1。'],
 't是球半径，不是积分中的球坐标变量r；别把角度积分或r平方体积因子漏掉。',r'$f(1)=\frac3{4\pi}(e^{4\pi/3}-1)$。')
add('G90',B,'证明式里有f和f导数：倒着找一次求导的乘积',['IMG151'],r'f在[a,b]连续、内部可导，$0<a<b,f(a)=0$。证明存在ξ使$af(\xi)+(\xi-b)f\prime(\xi)=0$。',[
 r'把目标改成$(b-x)f\prime(x)-af(x)=0$，想到$(b-x)^af(x)$的导数。',r'设$H(x)=(b-x)^af(x)$，因a>0且f连续，H在[a,b]连续；H(a)=H(b)=0。',r'在内部用罗尔，$H\prime(\xi)=(b-\xi)^{a-1}[(b-\xi)f\prime(\xi)-af(\xi)]=0$，前因子非零，得到目标。'],
 '指数用题中常数a没有问题；H在b处只要求连续，不要求可导。',r'存在这样的ξ；第一行设$H=(b-x)^af$。')
add('G91',B,'两个中值点各在半区间：同一辅助函数分两段用',['IMG152'],r'f在[0,1]连续、内部可导，$f(0)=0,f(1)=1/3$。证明存在$\xi\in(0,1/2),\eta\in(1/2,1)$，使$f\prime(\xi)+f\prime(\eta)=\xi^2+\eta^2$。',[
 r'想把右边平方移过去，先设$H(x)=f(x)-x^3/3$，它满足H(0)=H(1)=0。',r'分别在[0,1/2]、[1/2,1]用拉格朗日，得到$H\prime(\xi)=2H(1/2)$、$H\prime(\eta)=-2H(1/2)$。',r'两式相加，中间值抵消；再换回$H\prime=f\prime-x^2$。'],
 '不要硬找两个点的数值；半区间相同长度，正好让两个割线斜率相反。',r'两段中值定理相加即得。')
add('G92',B,'积分大过端点水平：先逼出内部的高点',['IMG166'],r'f在[0,1]二阶可导，$f(0)=0,f(1)=1,\int_0^1f=1$。①证明内部某点$f\prime=0$；②证明内部某点$f\prime\prime<-2$。',[
 r'若全程f≤1，由连续性且f(0)=0，积分严格小于1，矛盾。因此某内部点f>1，全局最大值在内部取得，导数为0。',r'第二问为制造-2，设$H=f-(2x-x^2)$。H两端为0，且$\int_0^1H=1/3>0$，所以存在c使H(c)>0。',r'令$Q(x)=H(c)x(1-x)/[c(1-c)]$，H-Q在0,c,1三点为0。连续用两次罗尔，某η处$H\prime\prime(\eta)=Q\prime\prime=-2H(c)/[c(1-c)]<0$。',r'H的二阶导是f的二阶导加2，于是$f\prime\prime(\eta)<-2$。'],
 '需要严格小于-2，不能只在极大点写二阶导不大于0；先减一条二阶导恰为-2的抛物线。',r'两个存在性结论均成立，第二问的辅助函数为$f-2x+x^2$。')
add('G93',B,'想证f二阶导等于f：把两阶算子拆成两次一阶',['IMG167'],r'f在[0,1]二阶可导，$\lim_{x\to0^+}f(x)/x=\lim_{x\to1^-}f(x)/(x-1)=1$。①证明内部有f的零点；②证明内部有$f\prime\prime=f$的点。',[
 r'由端点连续性与差商，f(0)=f(1)=0，端点单侧导数均为1。因此0右边f>0，1左边f<0，中间有零点。',r'设g=e的负x次方乘f，g(0)=g(1)=0；罗尔给某c满足g\prime(c)=0。',r'令$h=e^{2x}g\prime=e^x(f\prime-f)$。h(0)=1,h(1)=e，而h(c)=0，所以它在内部有一个最小值点η。',r'在η求导，$h\prime=e^x(f\prime\prime-f)=0$，得到所求。'],
 '第一问的端点极限要先变成端点值和端点斜率；第二问别强行对f直接连续用罗尔，目标多了一个f。',r'两个结论均成立。')
add('G94',C,'多元极限不是只试几条线：先找统一的界',['IMG062'],r'分别判断$xy^3/(x^2+y^4)$与$x^2/(x^4+y^4)$在原点的极限。并检查旧笔记“分母有奇数次，就说有歧义不考”的说法。',[
 r'第一式用$2|xy^2|\le x^2+y^4$，得绝对值不超过|y|/2，极限为0。',r'第二式沿y=0为1/x²，沿x=0为0，极限不存在。',r'路径比较用于否定；肯定极限要对所有路径给统一控制。分母某条曲线上无定义不等于极限“有歧义”，仍是在定义域内讨论，不能据此跳过题目。'],
 '旧图的幂次速判只在写清非负幂、偶数分母等前提后才可讨论，不能代替一般定义。',r'第一式极限0，第二式极限不存在；旧“有歧义不考”的推断删除。')
add('G95',C,'偏导存在只管坐标轴：轴外跳开，仍可不连续',['IMG063','IMG064'],r'$f(x,y)=x^2$（y=0），$f(x,y)=y^2$（x=0），其余点取1。判断原点偏导、连续、可微、偏导连续性。',[
 r'沿两轴差商，$f_x(0,0)=f_y(0,0)=0$。',r'沿y=x≠0，f恒为1，而原点f=0，所以不连续，必不可微。',r'还要注意附近轴上的横跨分段偏导可能根本不存在；不能只在xy≠0处求出偏导0就宣布偏导连续。'],
 '偏导的连续性要求这些偏导在所讨论邻域有定义并趋于点值，不能把不存在的点默默跳掉。',r'原点两个偏导存在且为0；不连续、不可微；不具备偏导连续性，原题D。')
add('G96',A,'斜着的大圆投影：消掉z，不把空间半径照搬到平面',[],r'C是单位球与x+y+z=0的交线，求在xOy上的投影方程。',[
 r'由平面解z=-x-y，代入球面，消掉z。',r'得到$2x^2+2xy+2y^2=1$，这是一条椭圆，不是单位圆。',r'若写成空间中投影曲线的方程，还加z=0；若只写平面坐标关系，就写前式。'],
 '大圆说的是空间中截圆半径最大，不表示它从任何方向看还是圆。',r'$2x^2+2xy+2y^2=1$（投影曲线另附z=0）。',refs=[(V,'第一题（大圆截面，投影还是不是圆？）')])
add('G97',A,'立体投影不是令z=0：问的是是否存在允许的高度',[],r'Ω由$z=2-x^2-y^2$与z=1围成，求xOy投影区域。',[
 r'先写这个立体真正的高度限制：$1\le z\le2-x^2-y^2$。',r'某个(x,y)能留下投影，必须存在这样的z，即下限不超过上限。',r'因此$1\le2-x^2-y^2$，得到单位圆盘。'],
 '令z=0是在求与地面的交截，不是在求悬空立体的影子；投影边界也不总能只找一条交线概括。',r'$D_{xy}:x^2+y^2\le1$。',refs=[(V,'第二题（立体投影，是令 $z=0$ 还是求交线？）')])
add('G98',A,'投到yOz，就检查有没有一个x能满足原条件',[],r'Ω满足$x^2+y^2\le4,0\le z\le2-y$，求yOz投影区域。',[
 r'保留y,z，消去x。能找到x满足$x^2\le4-y^2$，等价于$-2\le y\le2$。',r'z仍满足$0\le z\le2-y$；在上述y范围，上界非负。',r'边界点是(-2,0)、(-2,4)、(2,0)，所以yz平面上是三角形。'],
 '旧变式把它叫梯形，图形名称错误；不等式范围本身是对的。',r'$D_{yz}=\{(y,z):-2\le y\le2,0\le z\le2-y\}$，三角形。',refs=[(V,'第三题（换个面投影，到底消哪个字母？）')])
add('G99',H,'偶函数傅里叶只有奇数余弦项：总和减偶数和',['IMG179'],r'把$f(x)=2+|x|$（-1≤x≤1）作2周期傅里叶展开，并求$\sum_{n\ge1}1/n^2$。',[
 r'偶函数只算余弦，常数项a0/2=5/2；$a_n=2\int_0^1(2+x)\cos(n\pi x)dx=2[(-1)^n-1]/(n\pi)^2$。',r'因此只有奇数n留下：$f=5/2-(4/\pi^2)\sum_{k\ge0}\cos((2k+1)\pi x)/(2k+1)^2$。',r'代x=0得到奇数平方倒数和π²/8。若总和为T，偶数项和是T/4，所以3T/4=π²/8。'],
 '你原来标消灭，留傅里叶低频备用；总和不是直接等于奇数项和。',r'展开见步骤，$\sum1/n^2=\pi^2/6$。',main=False)
add('G100',H,'已知傅里叶恒等式的右边：反过来展开二次函数',['IMG188'],r'证明$\sum_{n\ge1}(-1)^{n-1}\cos(nx)/n^2=\pi^2/12-x^2/4$（-π≤x≤π），并求$\sum(-1)^{n-1}/n^2$。',[
 r'先展开偶函数x²：$x^2=\pi^2/3+4\sum_{n\ge1}(-1)^n\cos(nx)/n^2$，系数用两次分部积分得到。',r'移项并除以-4，就得到原恒等式；周期拼接处左右值都为π²，所以包括端点。',r'代x=0，余弦全部为1，得到交错平方和。'],
 '本题也已消灭，和G48同一个傅里叶系数来源，不把它们当两类高频任务重复做。',r'恒等式成立；交错平方和π²/12。',main=False)
# Additional source-only examples remain linked as reference; these three close genuine gaps in the supplied cards.
add('G101',C,'反函数求导：先找到对应的原函数输入',[],r'g是f的反函数，已知f在a可导且f(a)=b、f导数在a不为0，并满足反函数可导的局部条件，求g在b的导数。另核查旧反函数卡片中的具体例题条件。',[
 r'先写对应点$(a,b)\leftrightarrow(b,a)$。g的输入b，对应的是f的输入a，不是b。',r'对$f(g(y))=y$求导，在y=b得$f\prime(a)g\prime(b)=1$。',r'旧卡片同时写f\prime(1)=3与一个积分恒等式；对该恒等式在x=1求导却得到f\prime(1)=1，条件冲突，因此不把该例题的1/2当作可靠原题答案。'],
 '反函数公式$g\prime(b)=1/f\prime(a)$本身正确；旧例题的条件冲突是另一件事，不能拿它来背。',r'$g\prime(b)=1/f\prime(a)$。旧具体例题暂存疑，需核对原题，不编造缺失条件。',refs=[('04真题阶段/06卡片/01反函数.md','二、图一题目解析（怎么理解与求解）')])
add('G102',H,'偶次阶乘在分母，却是x的n次：把x当作根号的平方',['IMG072'],r'求$\sum_{n\ge0}(-1)^nx^n/(2n)!$在$(0,+\infty)$的和函数。',[
 r'先对照余弦展开$\cos t=\sum(-1)^nt^{2n}/(2n)!$，分母正好一致。',r'要把$t^{2n}$变成$x^n$，设$t=\sqrt x$，而不是把2n下标强行改成n。',r'x>0时得到$\cos\sqrt x$；若要延伸全实轴的级数，x<0时改认双曲余弦，但本题不需要。'],
 '这里是换变量，不是漏掉所有奇数项后还宣称原级数没变。',r'$S(x)=\cos\sqrt x$（x>0）。')
add('G103',C,'连续、偏导、可微：箭头只朝有依据的一边',[],r'把多元函数在一点的连续、偏导存在、可微、所有方向导数存在、偏导在邻域存在且在该点连续的关系整理清楚。',[
 r'偏导在邻域存在且在该点连续，可以推出该点可微；可微推出连续、偏导存在。',r'可微还推出任意单位方向的方向导数存在，并等于梯度与该单位向量的点积。只有某些、甚至所有方向导数存在，都不能直接反推可微；方向极限未必给出一个统一的一次近似。',r'要证可微，先按定义求点处两个偏导，再检查余项除以$\rho=\sqrt{h^2+k^2}$是否趋0；要否定连续或可微，可找一条坏路径。'],
 '“沿每条直线都行”与“所有方式一起趋近都行”不一样。不要把偏导存在当成整张曲面光滑。',r'主线：邻域偏导存在且点处连续⇒可微⇒连续；可微⇒偏导及所有方向导数存在。反向一般不成立。',refs=[('04真题阶段/00数学记忆.md','多元微分的点')])
add('G104',B,'两段反向积分先换元，移动中值点用误差控制',['IMG008'],r'f在[-1,1]连续，在0可导且$f\prime(0)\ne0$。①证对任意$x\in[0,1]$存在$\theta\in(0,1)$使$\int_0^xf+\int_0^{-x}f=x[f(\theta x)-f(-\theta x)]$；②求$x\to0^+$时θ的极限。',[
 r'第二个积分换元t=-s，左边变成$\int_0^x[f(t)-f(-t)]dt$。x>0时用积分中值定理，x=0任选θ。',r'令c=f\prime(0)不为0，h(t)=f(t)-f(-t)=2ct+o(t)。左边为cx²+o(x²)。',r'右边为2cθx²加$o(x²)$：这里误差可统一控制，因为$0<\theta x<x$。除以x²，得到c=2cθ+o(1)。'],
 '没有先假设θ有极限；先估计误差，再把θ单独解出来，这样才能证明它确实收敛。',r'θ存在，且任意满足该式的选择都有θ→1/2。')
add('G105',C,'绝对值乘一个可能为0的因子：别只数绝对值的零点',['IMG009'],r'$f(x)=(x^2-x-2)|x^3-x|$，求不可导点个数。',[
 r'绝对值内的零点为-1、0、1，其余点都是光滑函数相乘，先只查这三个点。',r'因$x^2-x-2=(x-2)(x+1)$，在-1处还有一个x+1，可把简单绝对值尖点压成$(x+1)|x+1|$，它在0型点可导。',r'在0、1处，绝对值外的剩余系数不为0，仍是非零常数乘简单尖点，所以不可导。'],
 '用的是$\varphi(x)|x-a|$在φ连续时可导当且仅当φ(a)=0；不是所有带绝对值的零点都不可导。',r'2个：0与1，原题B。')
add('G106',B,'求最小曲率半径：先把公式改成一个正函数',['IMG013','IMG051'],r'曲线$y=\ln x$在某点P的曲率半径最小，求该最小值。',[
 r'$y\prime=1/x,y\prime\prime=-1/x^2$，所以$R=(1+y\prime{}^2)^{3/2}/|y\prime\prime|=(x^2+1)^{3/2}/x$，x>0。',r'R为正，取对数求导更省：$(\ln R)\prime=3x/(x^2+1)-1/x$。',r'令其为0得$x^2=1/2$，导数在其左负右正，代回求最小值。'],
 '曲率越大，半径越小；不要把求最小半径算成最小曲率。',r'$R_{\min}=3\sqrt3/2$，在$x=1/\sqrt2$取得。',main=False)
add('G107',C,'不等式含单点：先代0，再夹导数差商',['IMG038','IMG039'],r'f在0的某邻域有定义，且$|f(x)|\le1-\cos x$。判断f在0是否连续、可导，导数是多少。',[
 r'题目不等式包括x=0，先代入得$|f(0)|\le0$，所以f(0)=0。',r'由$|f(x)|\le1-\cos x\to0$，先得连续。',r'再看$|[f(x)-f(0)]/x|\le(1-\cos x)/|x|\to0$，因此可导且导数0。'],
 '若题目只在去心邻域给不等式，仍需另外检查f(0)；不能自动把它补成0。',r'可导且$f\prime(0)=0$，原题选C。')
